\section{Introduction}

\subsection{Motivation}
Discrepancy theory measures how evenly a finite point set is distributed relative to a family
of test regions. In coding theory the relevant point set is a code $C \subseteq G$ and the
test regions are Hamming balls $\ball_r(z)$. A central conjecture predicts that a random
linear code of the appropriate dimension is \emph{equidistributed} for all Hamming balls
simultaneously: with probability $1-o(1)$, for \emph{every} centre $z$,
\[
  |C \cap \ball_r(z)| = (1 \pm o(1)) \cdot \frac{|C| \cdot |\ball_r|}{q^n}.
\]
Two distinct claims are bundled here: (i) that the \emph{target value} $|C|\cdot|\ball_r|/q^n$
is correct, and (ii) that the individual counts \emph{concentrate} around it for all centres
at once. This paper proves (i) unconditionally and exactly, and reduces (ii) to a clean
two-sided concentration question, isolating the upper tail as a consequence of (i).

\subsection{The duality principle}
The unifying technique is a duality between two ways of counting incidences in the relation
``codeword $c$ lies in the ball about centre $z$'': summing over centres first yields exact
mean-value and weight-budget statements (averaging view), while summing over codewords or
bounding a covering map yields existence/pigeonhole statements (coverage view). The same
duality reappears in numerical integration, where worst-case error equals a discrepancy and
non-negative rules require exponentially many nodes to reach a target accuracy --- the curse
of dimensionality. We formalize the combinatorial kernel of the averaging side.

\subsection{Contributions}
\begin{enumerate}
  \item Exact averaging identity (Theorem~\ref{thm:main}).
  \item Centre-independence of ball volume (Theorem~\ref{thm:vol}) from translation
        invariance (Lemma~\ref{lem:transinv}).
  \item Explicit ball-volume formula (Theorem~\ref{thm:volformula}).
  \item One-sided Markov discrepancy bound (Theorem~\ref{thm:markov}).
  \item Periodicity of the discrepancy field for linear/coset codes (Lemma~\ref{lem:periodic}).
\end{enumerate}

\section{Setup and Definitions}
Fix a finite index set $\iota$ with $|\iota| = n$ and a finite alphabet $\alpha$ with
$|\alpha| = q$. The ambient space is the product group $G = \{ x : \iota \to \alpha \}$ with
$|G| = q^n$ and coordinatewise addition.

\begin{definition}[Hamming distance]
For $x, y \in G$, \quad $d(x, y) = \#\{ i \in \iota : x_i \neq y_i \}$.
\end{definition}

\begin{definition}[Hamming ball]
For $r \in \N$ and $z \in G$, \quad $\ball_r(z) = \{ x \in G : d(x, z) \le r \}$.
\end{definition}

\begin{definition}[Hamming sphere]
$S_r(z) = \{ x \in G : d(x, z) = r \}$.
\end{definition}

\begin{definition}[Discrepancy count]
For a code $C \subseteq G$, the local count is $N_C(z) = |C \cap \ball_r(z)|$; its
discrepancy is the spread of $N_C(z)$ over $z$ relative to the mean $|C|\cdot|\ball_r|/q^n$.
\end{definition}

\section{Translation Invariance and Centre-Free Volume}

\begin{lemma}[Translation invariance; Lean: \texttt{hammingDist\_add\_right}]
\label{lem:transinv}
For all $x, y, a \in G$, \; $d(x + a, y + a) = d(x, y)$.
\end{lemma}
\begin{proof}
For each $i$, $(x+a)_i \neq (y+a)_i \iff x_i + a_i \neq y_i + a_i \iff x_i \neq y_i$, since
adding $a_i$ is injective. The indicator sets coincide coordinatewise, hence have equal
cardinality.
\end{proof}

\begin{lemma}[Ball is a translate of the origin ball; Lean: \texttt{ball\_eq\_image}]
\label{lem:balltranslate}
For all $r, z$, \; $\ball_r(z) = \{ y + z : y \in \ball_r(0) \}$.
\end{lemma}
\begin{proof}
For $x \in \ball_r(z)$ set $y = x - z$; Lemma~\ref{lem:transinv} gives $d(y, 0) = d(x, z) \le
r$. Conversely $y \in \ball_r(0)$ gives $d(y+z, z) = d(y, 0) \le r$. The map $y \mapsto y+z$
is a bijection between the sets.
\end{proof}

\begin{theorem}[Centre-independence of ball volume; Lean: \texttt{ball\_card\_eq}]
\label{thm:vol}
For all $r, z$, \; $|\ball_r(z)| = |\ball_r(0)|$.
\end{theorem}
\begin{proof}
Translation $y \mapsto y + z$ is injective, so by Lemma~\ref{lem:balltranslate} the ball
$\ball_r(z)$ is the injective image of $\ball_r(0)$ and has the same cardinality.
\end{proof}

\begin{lemma}[Centres containing a fixed point; Lean: \texttt{card\_centres\_containing}]
\label{lem:dual}
For any fixed $c \in G$, \; $\#\{ z \in G : d(c, z) \le r \} = |\ball_r(0)|$.
\end{lemma}
\begin{proof}
By symmetry of $d$, $d(c, z) \le r \iff z \in \ball_r(c)$, so the set is exactly
$\ball_r(c)$; apply Theorem~\ref{thm:vol}.
\end{proof}

\section{The Exact Averaging Identity}

\begin{theorem}[Exact averaging identity; Lean: \texttt{sum\_inter\_ball}]
\label{thm:main}
For every code $C \subseteq G$ and radius $r$,
\[
  \sum_{z \in G} |C \cap \ball_r(z)| \;=\; |C| \cdot |\ball_r(0)|.
\]
Equivalently, the average over centres of $N_C(z)$ is exactly $|C|\cdot|\ball_r|/q^n$.
\end{theorem}
\begin{proof}
Write $|C \cap \ball_r(z)| = \sum_{c \in C} \ind{d(c, z) \le r}$, substitute, and exchange
summation order:
\[
  \sum_{z} \sum_{c \in C} \ind{d(c, z) \le r}
  = \sum_{c \in C} \#\{ z : d(c, z) \le r \}
  = \sum_{c \in C} |\ball_r(0)| = |C| \cdot |\ball_r(0)|,
\]
using Lemma~\ref{lem:dual} for the inner count.
\end{proof}

\begin{remark}
The identity is exact, requires no structure on $C$, and would fail if ball volume depended on
the centre; this is why Lemma~\ref{lem:transinv} is load-bearing. Linearity of $C$ is not
assumed, so the statement is strictly more general than the conjecture's hypothesis.
\end{remark}

\begin{corollary}
Dividing by $|G| = q^n$ shows the conjecture's target value $|C|\cdot|\ball_r|/q^n$ is exactly
the mean; what remains is concentration about it.
\end{corollary}

\section{The Explicit Ball-Volume Formula}

\begin{lemma}[Sphere count; Lean: \texttt{sphere\_card}]
\label{lem:sphere}
$|S_r(0)| = \binom{n}{r}(q-1)^r$.
\end{lemma}
\begin{proof}
A point at distance $r$ from $0$ is determined by its support $T$, a size-$r$ subset of the
$n$ coordinates ($\binom{n}{r}$ choices), together with a nonzero symbol at each coordinate of
$T$ ($(q-1)^r$ choices). The map (point) $\mapsto$ (support, values) is a bijection. The
subtraction $q-1$ is truncated natural subtraction, valid since $q \ge 1$.
\end{proof}

\begin{lemma}[Ball as disjoint union of spheres; Lean: \texttt{ball\_card\_eq\_sum\_sphere}]
\label{lem:ballsum}
$|\ball_r(0)| = \sum_{i=0}^{r} |S_i(0)|$.
\end{lemma}
\begin{proof}
The inequality $d(x,0) \le r$ partitions by the exact value $d(x,0) = i$; the spheres are
disjoint and cover the ball.
\end{proof}

\begin{theorem}[Explicit ball volume; Lean: \texttt{ball\_card\_formula}]
\label{thm:volformula}
$|\ball_r(0)| = \sum_{i=0}^{r} \binom{n}{i}(q-1)^i$.
\end{theorem}
\begin{proof}
Combine Lemmas~\ref{lem:sphere} and~\ref{lem:ballsum}.
\end{proof}

\section{The One-Sided Discrepancy Bound}

\begin{theorem}[Markov discrepancy bound; Lean: \texttt{card\_bad\_centres\_le}]
\label{thm:markov}
For every code $C$, radius $r$, and threshold $t \ge 1$,
\[
  \#\{ z \in G : |C \cap \ball_r(z)| \ge t \} \cdot t \;\le\; |C| \cdot |\ball_r(0)|,
\]
hence the number of crowded centres is at most $|C|\cdot|\ball_r|/t$.
\end{theorem}
\begin{proof}
Let $H = \{ z : N_C(z) \ge t \}$. Then
\[
  |H| \cdot t = \sum_{z \in H} t \le \sum_{z \in H} N_C(z) \le \sum_{z \in G} N_C(z)
  = |C| \cdot |\ball_r(0)|,
\]
using $N_C \ge t$ on $H$, non-negativity of dropped terms, and Theorem~\ref{thm:main}.
\end{proof}

\begin{remark}
Theorem~\ref{thm:markov} controls only the upper tail: crowding is rare. It says nothing about
empty or under-subscribed centres. Full equidistribution requires a matching lower-tail
companion, which genuinely needs the randomness or linear structure absent here. The
decomposition exact-mean $+$ one-sided-tail is strictly weaker than two-sided concentration;
that gap is the residue of the conjecture.
\end{remark}

\section{Periodicity for Linear and Coset Codes}

\begin{lemma}[Coset periodicity; Lean: \texttt{inter\_ball\_coset\_invariant},
\texttt{inter\_ball\_eq\_of\_sub\_mem}]
\label{lem:periodic}
Let $C \subseteq G$ be a code closed under codeword translation. If $z - z' \in C$, then
$|C \cap \ball_r(z)| = |C \cap \ball_r(z')|$.
\end{lemma}
\begin{proof}
Translation by $z' - z$ is a bijection of $G$ mapping $\ball_r(z)$ onto $\ball_r(z')$
(Lemma~\ref{lem:balltranslate}) and mapping $C$ onto itself when $z - z' \in C$. A bijection
between the intersections preserves cardinality.
\end{proof}

For a linear code $z \mapsto N_C(z)$ is constant on cosets of $C$ and descends to $G/C$. The
discrepancy problem becomes equidistribution of a periodic function --- the formal link to
periodic $L_p$-discrepancy and the wrap-around spaces of the curse-of-dimensionality
literature.

\section{Algorithms}
\textbf{(A) Exact Mean via Averaging Identity.} Computes $|C|\cdot|\ball_r(0)|$ and the
per-centre mean without enumerating centres, using Theorems~\ref{thm:main}
and~\ref{thm:volformula}: $O(r)$ operations versus $\Theta(q^n)$ naive.\\
\textbf{(B) Discrepancy Profile by Direct Enumeration.} For small $G$, tabulate $N_C(z)$ over
all $q^n$ centres to certify the identity and study concentration; $\Theta(q^n |C|)$.\\
\textbf{(C) Crowded-Centre Budget Certificate.} Returns $\lfloor |C|\cdot|\ball_r|/t \rfloor$
(Theorem~\ref{thm:markov}) and optionally the true count for verification.

\section{Applications and Discussion}
The methodological lesson is that demanding an \emph{exact} statement, plus a deliberate
choice of which index to sum first, dissolves the apparently hard ``target value''
sub-problem. The residual difficulty --- lower-tail/two-sided concentration --- is now
cleanly exposed. Companion directions (not proved here): sign-asymmetry of the curse under
signed weights; a quantitative tractability threshold via iterated pigeonhole; a two-sided
discrepancy law pairing the Markov upper bound with a lower-tail companion; and a
reproducing-kernel reading of the combinatorial worst-case error.

\section{Conclusion}
A one-line double count, resting on translation invariance of Hamming distance, proves that
the average number of codewords in a Hamming ball is exactly $|C|\cdot|\ball_r|/q^n$ for every
code. The ball volume is centre-independent and explicitly $\sum_{i \le r}\binom{n}{i}(q-1)^i$.
The same identity bounds the upper tail of the discrepancy for free, and additive structure
makes the discrepancy field periodic. Together these separate the certain part of a known
conjecture from its genuinely hard residue, and provide the averaging engine for the duality
framework behind exponential lower bounds in high-dimensional computation.

